namespace ghidra.app.plugin.core.register;









using docking.widgets.tree;
using docking.widgets.tree;
using generic.theme;
using ghidra.program.model.lang;
using ghidra.program.model.listing;
using ghidra.util.datastruct;
using resources;

public class RegisterTree : GTree {
	private Program program;
	private RegisterTreeRootNode root;
	private bool isFiltered;

	public RegisterTree() : base(new RegisterTreeRootNode())
    {
		root = (RegisterTreeRootNode) getModelRoot();

		setEditable(false);

		getSelectionModel().setSelectionMode(TreeSelectionModel.SINGLE_TREE_SELECTION);
		setHorizontalScrollPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);

		// add change listener to prevent tree from scrolling horizontally since we will
		// never have a horizontal scroll bar.
		JScrollPane scrollPane = getScrollPane();
		JViewport viewport = scrollPane.getViewport();
		scrollPane.getViewport().addChangeListener(e => {
			Point viewPosition = viewport.getViewPosition();
			if (viewPosition.x != 0) {
				// if it scrolls horizontally, put it back
				viewPosition.x = 0;
				viewport.setViewPosition(viewPosition);
			}
		});
		setMinimumSize(new Dimension(175, 30));
	}

	void setProgram(Program program) {
		cancelWork();
		this.program = program;
		Register[] registers = null;
		if (program != null) {
			registers =
				isFiltered ? program.getProgramContext().getRegistersWithValues()
						: getNonHiddenRegisters(program);
		}
		else {
			registers = new Register[0];
		}
		root.setRegisters(registers);
	}

	private static Register[] getNonHiddenRegisters(Program program) {
		List<Register> list = new();
		foreach (Register reg in program.getProgramContext().getRegisters()) {
			if (!reg.isHidden()) {
				list.add(reg);
			}
		}

		return list.toArray(Register[].new);
	}

	void setFiltered(bool b) {
		isFiltered = b;
		if (program != null) {
			Register[] registers =
				isFiltered ? program.getProgramContext().getRegistersWithValues()
						: getNonHiddenRegisters(program);
			root.setRegisters(registers);
		}
	}

	public void selectRegister(Register register) {
		GTreeNode node = root.findNode(register);
		if (node != null) {
			TreePath path = node.getTreePath();
			setSelectionPath(path);
			scrollPathToVisible(path);
		}
	}

	public void updateFilterList() {
		if (isFiltered) {
			Register currentRegister = getSelectedRegister();
			Register[] registers = program.getProgramContext().getRegistersWithValues();
			root.setRegisters(registers);
			selectRegister(currentRegister);
		}
	}

	Register getSelectedRegister() {
		TreePath selectionPath = getSelectionPath();
		if (selectionPath == null) {
			return null;
		}

		object item = selectionPath.getLastPathComponent();
		if (item is RegisterTreeNode) {
			return ((RegisterTreeNode) item).getRegister();
		}
		return null;
	}

	private static class RegisterNodeComparator : Comparator<GTreeNode> {

		private AlphaNumericComparator alphaNumericComparator =
			new AlphaNumericComparator();

		/* @Override */
		public int compare(GTreeNode n1, GTreeNode n2) {
			string s1 = n1.getName().toLowerCase();
			string s2 = n2.getName().toLowerCase();
			return alphaNumericComparator.compare(s1, s2);
		}
	}

	private static abstract class SearchableRegisterTreeNode : GTreeNode {

		private RegisterNodeComparator comparator = new RegisterNodeComparator();

		void sortChildren() {
			List<GTreeNode> children = new(children());
			Collections.sort(children, comparator);
			setChildren(children);

			foreach (GTreeNode child in children) {
				SearchableRegisterTreeNode regNode = (SearchableRegisterTreeNode) child;
				regNode.sortChildren();
			}
		}

		public GTreeNode findNode(Register register) {
			List<GTreeNode> allChildren = getChildren();
			foreach (GTreeNode child in allChildren) {
				if (!(child is RegisterTreeNode)) {
					continue;
				}
				RegisterTreeNode node = (RegisterTreeNode) child;
				if (node.getRegister().equals(register)) {
					return node;
				}

				GTreeNode foundNode = ((SearchableRegisterTreeNode) child).findNode(register);
				if (foundNode != null) {
					return foundNode;
				}
			}

			return null;
		}
	}

	private static class RegisterTreeNode : SearchableRegisterTreeNode {
		private static Icon REG_ICON = new GIcon("icon.plugin.register");
		private static Icon REG_GROUP_ICON = new GIcon("icon.plugin.register.provider");
		private Register register;

		public RegisterTreeNode(Register register) {
			this.register = register;
			foreach (Register childRegister in register.getChildRegisters()) {
				addNode(new RegisterTreeNode(childRegister));
			}
		}

		/* @Override */
		public Icon getIcon(bool expanded) {
			return register.hasChildren() ? REG_GROUP_ICON : REG_ICON;
		}

		/* @Override */
		public string getName() {
			return register.getName() + "  (" + register.getBitLength() + getAliases() +
				")";
		}

		private string getAliases() {
			StringBuffer buf = new StringBuffer();
			foreach (string alias in register.getAliases()) {
				buf.append(buf.length() == 0 ? "; " : ", ");
				buf.append(alias);
			}
			return buf.toString();
		}

		/* @Override */
		public string getToolTip() {
			return register.getDescription();
		}

		/* @Override */
		public bool isLeaf() {
			return !register.hasChildren();
		}

		Register getRegister() {
			return register;
		}
	}

	private static class RegisterTreeGroupNode : SearchableRegisterTreeNode {
		private static Icon OPEN_ICON = Icons.OPEN_FOLDER_ICON;
		private static Icon CLOSED_ICON = Icons.CLOSED_FOLDER_ICON;
		private string name;

		public RegisterTreeGroupNode(string name) {
			this.name = name;
		}

		/* @Override */
		public Icon getIcon(bool expanded) {
			return expanded ? OPEN_ICON : CLOSED_ICON;
		}

		/* @Override */
		public string getName() {
			return name;
		}

		/* @Override */
		public string getToolTip() {
			return null;
		}

		/* @Override */
		public bool isLeaf() {
			return false;
		}

		public void addRegister(Register register) {
			addNode(new RegisterTreeNode(register));
		}
	}

	private static class RegisterTreeRootNode : SearchableRegisterTreeNode {
		private Register[] lastRegisters;

		/* @Override */
		public Icon getIcon(bool expanded) {
			return null;
		}

		/* @Override */
		public string getName() {
			return "Registers";
		}

		/* @Override */
		public string getToolTip() {
			return null;
		}

		/* @Override */
		public bool isLeaf() {
			return false;
		}

		public void setRegisters(Register[] registers) {
			if (registers == lastRegisters) {
				return;
			}

			removeAll(); // remove all current children before re-populating

			lastRegisters = registers;
			Dictionary<string, RegisterTreeGroupNode> groups = new();

			List<GTreeNode> nodes = new();

			foreach (Register register in registers) {
				if (register.getBaseRegister() != register &&
					!register.getParentRegister().isHidden()) {
					continue;
				}

				string groupName = register.getGroup();
				if (groupName != null) {
					RegisterTreeGroupNode group = groups.get(groupName);
					if (group == null) {
						group = new RegisterTreeGroupNode(groupName);
						groups.put(groupName, group);
						nodes.add(group);
					}
					group.addRegister(register);
				}
				else {
					nodes.add(new RegisterTreeNode(register));
				}
			}

			setChildren(nodes);
			sortChildren();
		}

	}
}
